WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-EC-001-01', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_federal_resident_rights', 'federal + state', 'federal + state -- ALL_STATES', 'Federal Resident Rights Under the Nursing Home Reform Act', 'federal_agency | state_survey_agency', 'nursing_home_federal_resident_rights', 'https://www.medicare.gov/care-compare/', 'CMS: 800-633-4227 | Long-Term Care Ombudsman: 800-677-1116 | Your state survey agency -- see jurisdiction table', 'Nursing Home Reform Act (42 U.S.C. sec. 1395i-3 and 1396r) | Requirements for Long-Term Care Facilities (42 CFR Part 483, Subpart B) | Resident rights (42 CFR 483.10) | Freedom from abuse, neglect, and exploitation (42 CFR 483.12) | Elder Justice Act crime reporting (42 U.S.C. sec. 1320b-25)', 'VERIFIED', '2026-08-17', 'CONFIRM MEDICARE/MEDICAID CERTIFICATION ON CARE COMPARE FIRST -- it determines whether this federal rulebook applies at all, and it hands you the facility''s inspection history, staffing data, and penalty record for free. Then cite 42 CFR 483.10 or 483.12 by section in your complaint. A complaint that names the federal requirement is processed differently from one that describes only harm. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 22a27726ef652d6e06a4b4e3bdf60341511077359177b304f4d9eaba30295889]', 'v1.0'),
('SAIS-EC-001-02', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_survey_agency_complaint', 'state', 'state -- ALL_STATES', 'State Survey Agency Complaint -- The Enforcement Track With Federal Teeth', 'state_survey_agency | federal_agency', 'nursing_home_survey_agency_complaint', 'https://www.medicare.gov/care-compare/', 'Your state survey agency (health department) -- see jurisdiction table | CMS: 800-633-4227', 'Requirements for Long-Term Care Facilities (42 CFR Part 483) | Survey, certification, and enforcement procedures (42 CFR Part 488) | Civil money penalties (42 CFR 488.430 et seq.) | State facility licensing acts | Freedom of Information Act and state public records acts.', 'VERIFIED', '2026-08-17', 'SAY ''IMMEDIATE JEOPARDY'' IF THE FACTS SUPPORT IT, AND CITE THE FEDERAL TAG. Those two things move an allegation from a 45-day queue to a 2-day on-site survey. Afterward, pull the CMS-2567 and the plan of correction, and check Care Compare for prior citations on the same requirement -- repeat deficiencies are the strongest evidence available and cost nothing to obtain. [address_resolution: Resolve via the state health department survey agency regional office; input = facility county. Complaints are commonly filed to a regional intake address, not the state capital.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 5d87fdcc06def74d33d9847d18db451ef50512b7c07f8da6ac21b9fa2f707c34]', 'v1.0'),
('SAIS-EC-001-03', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_parallel_reporting_tracks', 'federal + state', 'federal + state -- ALL_STATES', 'The Four Parallel Reporting Tracks -- and Why All Four Matter', 'federal_program | state_agency | law_enforcement', 'nursing_home_parallel_reporting_tracks', 'https://oig.hhs.gov/fraud/report-fraud/', 'LTC Ombudsman: 800-677-1116 | Adult Protective Services via Eldercare Locator: 800-677-1116 | 911 | Your state Medicaid Fraud Control Unit (through the state Attorney General)', 'Elder Justice Act (42 U.S.C. sec. 1397j et seq.; crime reporting at 42 U.S.C. sec. 1320b-25) | Medicaid Fraud Control Units (42 U.S.C. sec. 1396b(q); 42 CFR Part 1007) | Older Americans Act LTC Ombudsman (42 U.S.C. sec. 3058g) | State adult protective services and vulnerable adult abuse statutes.', 'VERIFIED', '2026-08-17', 'REFER TO THE MEDICAID FRAUD CONTROL UNIT WHERE THE PROBLEM LOOKS SYSTEMIC. MFCU jurisdiction covers resident abuse and neglect, not just billing, and it carries criminal investigative authority that no other track here has. File all four -- Ombudsman, APS, law enforcement, MFCU -- because none of them reliably notifies the others. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 6a31377e84aed7351dc5f84d5e645f787e80891db535c4830825837e274635c6]', 'v1.0'),
('SAIS-EC-001-04', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_involuntary_discharge', 'federal + state', 'federal + state -- ALL_STATES', 'Involuntary Transfer or Discharge -- Limited Grounds and a Very Short Hearing Clock', 'federal_agency | state_agency', 'nursing_home_involuntary_discharge', 'https://theconsumervoice.org/get_help', 'LTC Ombudsman (call today): 800-677-1116 | Your state survey agency | State fair hearing office', 'Transfer and discharge requirements (42 CFR 483.15(c)) | Bed-hold and readmission (42 CFR 483.15(d) and (e)) | Resident rights (42 CFR 483.10) | Nursing Home Reform Act (42 U.S.C. sec. 1395i-3(c), 1396r(c)) | State fair hearing procedures.', 'VERIFIED', '2026-08-17', 'CALL THE OMBUDSMAN THE DAY THE NOTICE ARRIVES AND REQUEST THE HEARING BEFORE THE EFFECTIVE DATE. Do not move out first. Then read the notice against 42 CFR 483.15(c) -- if it does not state a permitted ground, the effective date, the destination, appeal rights, and the Ombudsman''s contact information, it is defective on its face and that alone is a basis to stop it. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 054f2de709738b20611168e87c060af1fc7dd70e7ab147ea379552a96f42ae18]', 'v1.0'),
('SAIS-EC-001-05', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_records_and_evidence', 'federal + state', 'federal + state -- ALL_STATES', 'Records, Payroll-Based Staffing Data, and the Preservation Letter', 'federal_agency | state_court', 'nursing_home_records_and_evidence', 'https://www.medicare.gov/care-compare/', 'HHS Office for Civil Rights (records access): 800-368-1019 | CMS Care Compare (public staffing data) | Your state bar lawyer referral service', 'HIPAA right of access (45 CFR 164.524) | Payroll-Based Journal staffing submission (42 CFR 483.70) | Arbitration agreements (42 CFR 483.70(n)) | Clinical records requirements (42 CFR 483.70(i)) | State wrongful death and survival statutes.', 'VERIFIED', '2026-08-17', 'PULL THE PUBLIC PAYROLL-BASED STAFFING DATA FROM CARE COMPARE AND SEND THE PRESERVATION LETTER THE SAME DAY. The staffing data is free, public, and converts an individual charting failure into a documented facility condition. Name the ELECTRONIC AUDIT TRAIL explicitly in the records request -- it shows late and amended entries and it is almost never produced unless specifically demanded. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0698b51edeb499fd37f039470cbcfe0fa42341c3bb680f69f125aca44ad2029e]', 'v1.0'),
('SAIS-EC-001-06', 'systemic_abuse_intelligence', 301, 'nursing_home_abuse', 'nursing_home_chemical_restraint', 'federal + state', 'federal + state -- ALL_STATES', 'Chemical Restraint -- Antipsychotic Medication Without a Qualifying Diagnosis', 'federal_agency | state_survey_agency', 'nursing_home_chemical_restraint', 'https://www.medicare.gov/care-compare/', 'Your state survey agency -- see jurisdiction table | LTC Ombudsman: 800-677-1116 | State Board of Pharmacy | State medical board', 'Freedom from restraints (42 CFR 483.10(e)(1); 483.12(a)(2)) | Unnecessary drugs and antipsychotic requirements (42 CFR 483.45(d) and (e)) | Drug regimen review (42 CFR 483.45(c)) | Nursing Home Reform Act (42 U.S.C. sec. 1395i-3(c)(1)(A)(ii))', 'VERIFIED', '2026-08-17', 'ASK WHETHER THE DIAGNOSIS PREDATES THE PRESCRIPTION. A qualifying diagnosis that appears in the record only after the antipsychotic was started is the single most telling pattern in this allegation type, and it is visible in the record you can request today. Cite 42 CFR 483.45(e) by section, request the pharmacist''s monthly drug regimen review, and check the facility''s published antipsychotic use rate on Care Compare. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-001 | pipeline: Nursing Home Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 36f19066e0e8e6529dd5f0d53cb5094cdd5d56a9a0f407e8e6cab18b05247df8]', 'v1.0'),
('SAIS-EC-002-01', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_immediate_asset_protection', 'federal + state', 'federal + state -- ALL_STATES', 'Immediate Asset Protection -- Freezes, Disbursement Holds, and Trusted Contacts', 'financial_institution | federal_agency', 'elder_financial_exploitation_immediate_asset_protection', 'https://ovc.ojp.gov/program/stop-elder-fraud', 'DOJ National Elder Fraud Hotline: 833-372-8311 | Your bank or credit union fraud department | FINRA Securities Helpline for Seniors | CFPB: 855-411-2372', 'Senior Safe Act (Pub. L. 115-174, sec. 303; 12 U.S.C. sec. 3423 note) | FINRA Rule 2165 (temporary holds) and Rule 4512 (trusted contact person) | Electronic Fund Transfer Act / Regulation E (15 U.S.C. sec. 1693; 12 CFR Part 1005) | Fair Credit Billing Act (15 U.S.C. sec. 1666) | FinCEN elder financial exploitation reporting guidance.', 'VERIFIED', '2026-08-17', 'SAY THE WORDS ''FINANCIAL EXPLOITATION OF AN OLDER ADULT'' TO THE INSTITUTION AND ASK BROKERAGES FOR A TEMPORARY HOLD UNDER FINRA RULE 2165 BY NAME. Institutions have specific authority here that they do not volunteer, and employees are protected when they act. Then watch the 60-day Regulation E window on unauthorized electronic transfers -- it is the shortest deadline in this pipeline and it runs from the statement date, not from discovery. [address_resolution: Resolve via the institution''s own branch locator; input = ZIP. Fraud and exploitation matters are handled by a central department reachable from any branch.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 294d977b2f1754719166b903988a7334137f8160192a67fa8fb56286c37162dc]', 'v1.0'),
('SAIS-EC-002-02', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_reporting', 'federal + state', 'federal + state -- ALL_STATES', 'Reporting Financial Exploitation -- Four Bodies, None of Which Notifies the Others', 'state_agency | law_enforcement | federal_agency', 'elder_financial_exploitation_reporting', 'https://reportfraud.ftc.gov/', 'DOJ National Elder Fraud Hotline: 833-372-8311 | Adult Protective Services via Eldercare Locator: 800-677-1116 | Local law enforcement | FBI IC3 for online fraud', 'Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Elder Abuse Prevention and Prosecution Act (Pub. L. 115-70) | State vulnerable adult financial exploitation statutes | State adult protective services acts | 18 U.S.C. sec. 1341, 1343 (mail and wire fraud) where interstate conduct is involved.', 'VERIFIED', '2026-08-17', 'CALL 833-372-8311 FIRST IF YOU DO NOT KNOW WHERE TO START. The DOJ National Elder Fraud Hotline assigns a case manager who routes the report to every agency with jurisdiction and follows up -- which is exactly the coordination problem this pipeline creates. Then file the police report early: many institutions will not reverse a transaction without one, and the report number is required downstream. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: c2a36d866bbe8fd358be3427ecb2bb29ba8d9707ca32d9164e674f137f61dd5d]', 'v1.0'),
('SAIS-EC-002-03', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_money_trail', 'state', 'state -- ALL_STATES', 'Building the Money Trail and Documenting Undue Influence', 'financial_institution | state_court', 'elder_financial_exploitation_money_trail', 'https://www.lawhelp.org/', 'Your bank or credit union records department | County recorder of deeds | Your state bar lawyer referral service | Dial 211 for legal aid', 'State undue influence and financial exploitation statutes | Uniform Power of Attorney Act (2006) agent duties and accounting | State probate and trust codes | Right to Financial Privacy Act (12 U.S.C. sec. 3401 et seq.) | State recording acts.', 'VERIFIED', '2026-08-17', 'BUILD A DATED TIMELINE PLACING EVERY FINANCIAL CHANGE NEXT TO THE OLDER ADULT''S HEALTH AND COGNITION AND THE SUSPECTED PERSON''S ARRIVAL. That timeline is the case. Request cancelled checks with the BACK of each one -- the endorsement shows who took the money -- and send preservation demands immediately, because branch and ATM video is typically gone within 30-90 days. [address_resolution: Resolve via the institution''s own branch locator; input = ZIP. Fraud and exploitation matters are handled by a central department reachable from any branch.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 5a3a4720ccad5cad849147a22a6f7cb4c43d362ab3a60829f47e22f45c3a9e8d]', 'v1.0'),
('SAIS-EC-002-04', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_benefits_and_identity', 'federal', 'federal -- NATIONWIDE', 'Representative Payee Misuse, Benefit Redirection, and Identity Protection', 'federal_agency | credit_reporting_agency', 'elder_financial_exploitation_benefits_and_identity', 'https://www.identitytheft.gov/', 'SSA: 800-772-1213 | VA Fiduciary Program | FTC Identity Theft: 877-438-4338 | Annual Credit Report: 877-322-8228', 'Social Security representative payee provisions (42 U.S.C. sec. 405(j); 20 CFR Part 404 Subpart U) | Strengthening Protections for Social Security Beneficiaries Act | VA fiduciary program (38 U.S.C. sec. 5502; 38 CFR Part 13) | Fair Credit Reporting Act (15 U.S.C. sec. 1681; identity theft block at sec. 1681c-2)', 'VERIFIED', '2026-08-17', 'IF A REPRESENTATIVE PAYEE IS INVOLVED, REPORT MISUSE TO SSA AND ASK ABOUT REISSUANCE BY NAME. SSA can replace the payee and, in defined misuse cases, repay the beneficiary -- which is a recovery route that exists nowhere else in this pipeline. If accounts were opened in the older adult''s name, get the FTC Identity Theft Report first: it unlocks the mandatory 4-business-day credit block, which ordinary disputes cannot match. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4e6f5c50dda0b5a5269084793da37763ff453a59c65b72aefd03dfb38933b27d]', 'v1.0'),
('SAIS-EC-002-05', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_civil_recovery', 'state', 'state -- ALL_STATES', 'Civil Recovery -- Void Transfers, Constructive Trusts, and Enhanced Elder Remedies', 'state_court', 'elder_financial_exploitation_civil_recovery', 'https://www.lawhelp.org/', 'Your state bar lawyer referral service | Dial 211 for legal aid and elder law referrals | State Attorney General elder abuse unit', 'Uniform Voidable Transactions Act (adopted in most states) | Uniform Power of Attorney Act (2006) | State statutory elder financial abuse remedies with fee-shifting | State probate codes and will contest periods | State forfeiture-on-exploitation provisions.', 'VERIFIED', '2026-08-17', 'ASK ABOUT ASSET PRESERVATION IN THE FIRST CONVERSATION WITH ANY ATTORNEY, AND ASK WHETHER YOUR STATE HAS A STATUTORY ELDER FINANCIAL ABUSE CLAIM WITH FEE-SHIFTING. Those two questions determine whether there is anything left to recover and whether anyone can afford to pursue it. Where a fiduciary is involved, the petition to compel an accounting is faster and cheaper than a damages suit and does not require proving misconduct first. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 2702572a8f79e43c9e0d66c746be2420592834189fafa90171cdc8661a2fa0e4]', 'v1.0'),
('SAIS-EC-002-06', 'systemic_abuse_intelligence', 302, 'elder_financial_exploitation', 'elder_financial_exploitation_prevention', 'federal + state', 'federal + state -- ALL_STATES', 'Prevention -- Trusted Contacts, Monitoring, and Structural Safeguards', 'financial_institution | federal_agency', 'elder_financial_exploitation_prevention', 'https://www.consumerfinance.gov/consumer-tools/educator-tools/resources-for-older-adults/', 'CFPB Money Smart for Older Adults | Your bank or credit union | Eldercare Locator: 800-677-1116 | Your state securities regulator', 'FINRA Rule 4512 (trusted contact person) and Rule 2165 (temporary holds) | Senior Safe Act (Pub. L. 115-174, sec. 303) | Fair Credit Reporting Act security freeze provisions (15 U.S.C. sec. 1681c-1) | Telephone Consumer Protection Act (47 U.S.C. sec. 227) | Uniform Power of Attorney Act (2006)', 'VERIFIED', '2026-08-17', 'ADD A TRUSTED CONTACT PERSON AND TRANSACTION ALERTS TO EVERY ACCOUNT TODAY. Both are free, take minutes, transfer no authority, and are the two safeguards that most reliably surface exploitation early. Then ask about READ-ONLY VIEW ACCESS for a family member -- visibility without control is the right setting for most families and almost no institution offers it unprompted. [address_resolution: Resolve via the institution''s own branch locator; input = ZIP. Fraud and exploitation matters are handled by a central department reachable from any branch.] [doc_code: EC-002 | pipeline: Elder Financial Exploitation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: bbe416c1659e646cf1bca3252b06cf8ea337941b32470a63b3aaadbcde45a6ec]', 'v1.0'),
('SAIS-EC-003-01', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_order_review', 'state', 'state -- ALL_STATES', 'Read the Guardianship Order First -- Scope Determines Everything', 'state_court', 'guardianship_abuse_order_review', 'https://www.americanbar.org/groups/law_aging/', 'The probate or guardianship court clerk that issued the order | Court self-help center -- see jurisdiction table | Dial 211 for legal aid', 'Uniform Guardianship, Conservatorship, and Other Protective Arrangements Act (UGCOPAA, 2017) | Uniform Adult Guardianship and Protective Proceedings Jurisdiction Act (UAGPPJA) | State guardianship and probate codes | Americans with Disabilities Act (42 U.S.C. sec. 12101)', 'VERIFIED', '2026-08-17', 'PULL THE DOCKET AND CHECK WHETHER THE REQUIRED REPORTS AND ACCOUNTINGS WERE ACTUALLY FILED. A guardian who is behind on court-ordered reporting is already in violation, and you can see it for free without proving anything. Then read the order for rights EXPRESSLY RETAINED -- blocked visitation or communication where the order left that right intact is overreach you can raise immediately. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f773bd192ba3a5c7ea417857db80f11070f2df46df573d3fb720af514d2d56c2]', 'v1.0'),
('SAIS-EC-003-02', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_fiduciary_duties', 'state', 'state -- ALL_STATES', 'Guardian and Conservator Duties -- What the Law Actually Requires', 'state_court', 'guardianship_abuse_fiduciary_duties', 'https://www.americanbar.org/groups/law_aging/', 'Your probate court clerk | State guardianship oversight or certification program | Your state bar lawyer referral service', 'UGCOPAA (2017) sec. 313-318 (guardian duties and reports), sec. 418-423 (conservator duties, inventory, accountings) | State guardianship and probate codes | State guardian certification and bonding statutes.', 'VERIFIED', '2026-08-17', 'CALENDAR THE OBJECTION DEADLINE THE DAY AN ACCOUNTING IS NOTICED. It is commonly 20-30 days, and an approved accounting is very hard to reopen -- which means transactions you never examined become final. Also note the modern standard: a guardian must give effect to the person''s PREFERENCES AND VALUES, not merely act on their own view of the person''s best interest. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 437e8ff7e26bfc8b9810272878f084ff16a634e34e497dcc1a3926f279462779]', 'v1.0'),
('SAIS-EC-003-03', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_petition_court_review', 'state', 'state -- ALL_STATES', 'Petition for Court Review -- The Tool That Does Not Require Proof', 'state_court', 'guardianship_abuse_petition_court_review', 'https://www.lawhelp.org/', 'The probate court that issued the order | Court self-help center | Dial 211 for legal aid and elder law referrals', 'UGCOPAA (2017) sec. 116 (court authority and appointment of visitor), sec. 318 (removal and modification), sec. 431 (conservator accountings) | UAGPPJA | State guardianship codes | Elder Abuse Prevention and Prosecution Act (Pub. L. 115-70)', 'VERIFIED', '2026-08-17', 'ASK FOR A COURT VISITOR OR GUARDIAN AD LITEM IN THE PETITION. It is the highest-value request available because it places an independent party in front of the protected person and produces a neutral report the court will weigh heavily -- and it does not depend on the petitioner already having evidence. Pair it with a request for emergency relief if a home is being sold or the person is being moved. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 1d5842f4e0beb0bd9af7d31e6cec72b70b178f7b1547d3c4c157fa4343c98b3f]', 'v1.0'),
('SAIS-EC-003-04', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_isolation_and_visitation', 'state', 'state -- ALL_STATES', 'Isolation, Visitation, and Communication Rights', 'state_court | state_agency', 'guardianship_abuse_isolation_and_visitation', 'https://eldercare.acl.gov/', 'The probate court that issued the order | Adult Protective Services via Eldercare Locator: 800-677-1116 | Long-Term Care Ombudsman if in a facility: 800-677-1116', 'UGCOPAA (2017) sec. 313 (guardian duties, preservation of relationships) | State guardianship visitation and notification statutes | Resident visitation rights (42 CFR 483.10(f)(4)) | State adult protective services acts.', 'VERIFIED', '2026-08-17', 'TREAT ISOLATION AS THE EMERGENCY IT IS AND ATTACK IT ON THREE FRONTS AT ONCE -- a written demand to the guardian, a petition to the court for visitation, and, if the person is in a facility, the Long-Term Care Ombudsman, because resident visitation rights exist independently of any guardianship order. Isolation is both the violation and the mechanism that hides every other one. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e537000ed4cb7084a4c1ef5e88775825792967e9ef0c6dce99c8beb5c9bbb087]', 'v1.0'),
('SAIS-EC-003-05', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_removal_and_reporting', 'state', 'state -- ALL_STATES', 'Removing a Guardian and Reporting Misconduct', 'state_court | state_agency | law_enforcement', 'guardianship_abuse_removal_and_reporting', 'https://ovc.ojp.gov/program/stop-elder-fraud', 'The probate court that issued the order | Adult Protective Services: 800-677-1116 | Your state Attorney General | State guardian certification or oversight program', 'UGCOPAA (2017) sec. 318 (removal of guardian), sec. 430-431 (conservator liability and accountings) | Elder Abuse Prevention and Prosecution Act (Pub. L. 115-70) | Protection and Advocacy for Individuals with Mental Illness Act (42 U.S.C. sec. 10801 et seq.); PADD (42 U.S.C. sec. 15041 et seq.) | State guardian certification statutes.', 'VERIFIED', '2026-08-17', 'PROPOSE A SPECIFIC SUCCESSOR IN THE REMOVAL PETITION AND NOTIFY THE BOND SURETY IN WRITING. Courts hesitate to remove a guardian without knowing who takes over, and the bond is frequently the only collectible source of recovery once funds are gone. Then file with the STATE GUARDIAN CERTIFICATION PROGRAM if the guardian is a professional -- that route can stop them from serving other people, which the individual case will not. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 967de45bac2255e54ef6e731ef689f84b9a1de9dabc9a4efff338c47ca9a6049]', 'v1.0'),
('SAIS-EC-003-06', 'systemic_abuse_intelligence', 303, 'guardianship_abuse', 'guardianship_abuse_restoration_of_rights', 'state', 'state -- ALL_STATES', 'Restoration of Rights -- Guardianship Is Not Permanent', 'state_court', 'guardianship_abuse_restoration_of_rights', 'https://www.americanbar.org/groups/law_aging/', 'The probate court that issued the order | Court self-help center | State protection and advocacy agency | Dial 211 for legal aid', 'UGCOPAA (2017) sec. 318 (termination and modification), sec. 301 (basis for appointment; least restrictive), sec. 310 (limited guardianship) | State supported decision-making statutes | Americans with Disabilities Act (42 U.S.C. sec. 12101) | Olmstead v. L.C., 527 U.S. 581 (1999)', 'VERIFIED', '2026-08-17', 'FILE FOR RESTORATION -- THE WINDOW NEVER CLOSES. The right to petition belongs to the protected person and in most states even an informal letter to the judge must be treated as a petition. Ask for a CURRENT evaluation, because the original is usually years old and was made during a crisis, and name the less restrictive alternatives explicitly. Where full termination is denied, ask in the alternative for specific rights back -- partial restoration is granted far more often than families expect. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-003 | pipeline: Guardianship Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 434c09478c5ac56d1e67f4fbaf20541bb9d9231db5deadc0dc897f6b53ac20e8]', 'v1.0'),
('SAIS-EC-004-01', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_statement_review', 'federal', 'federal -- NATIONWIDE', 'The Medicare Summary Notice and Explanation of Benefits', 'federal_agency | federal_program', 'medicare_fraud_statement_review', 'https://www.medicare.gov/basics/reporting-medicare-fraud-and-abuse', 'Medicare: 800-633-4227 | TTY 877-486-2048 | Senior Medicare Patrol: 877-808-2468 | MyMedicare.gov account', 'Social Security Act Title XVIII (42 U.S.C. sec. 1395 et seq.) | Medicare claims appeals (42 CFR Part 405 Subpart I) | False Claims Act (31 U.S.C. sec. 3729 et seq.) | Senior Medicare Patrol (Older Americans Act, 42 U.S.C. sec. 3001 et seq.)', 'VERIFIED', '2026-08-17', 'OPEN A FREE MYMEDICARE ACCOUNT AND CHECK CLAIMS MONTHLY. Claims post within about 24 hours versus a quarterly paper notice, and in fraud the difference between catching it in a month and catching it in a quarter is most of the recoverable exposure. Then cross-check any suspicious billed date against a calendar -- a billed service on a date the beneficiary was demonstrably elsewhere is the single most actionable report you can file. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e4642e7a999c107b3c5a3780fd859cc80ff5904cd1c4935504de93dbacbef66b]', 'v1.0'),
('SAIS-EC-004-02', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_senior_medicare_patrol', 'federal + state', 'federal + state -- ALL_STATES', 'Senior Medicare Patrol -- Trained, Free, and Built for Exactly This', 'federal_program', 'medicare_fraud_senior_medicare_patrol', 'https://www.smpresource.org/', 'Senior Medicare Patrol: 877-808-2468 | Eldercare Locator: 800-677-1116 | Your state SHIP for coverage questions', 'Older Americans Act (42 U.S.C. sec. 3001 et seq.) -- Senior Medicare Patrol authorization | Health Insurance Portability and Accountability Act, fraud and abuse control program (42 U.S.C. sec. 1395i-3a) | State Health Insurance Assistance Program (42 U.S.C. sec. 1395b-4)', 'VERIFIED', '2026-08-17', 'CALL 877-808-2468 BEFORE TRYING TO INTERPRET THE STATEMENTS ALONE. The Senior Medicare Patrol will review them line by line at no cost, tell you whether what you are seeing is an error or probable fraud, and route the report properly -- which is the difference between a report that gets investigated and one that does not. Note that SMP handles FRAUD while SHIP handles COVERAGE; both are free, and many families need both. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 588e61f404a946a572e70a53ee125ec7ceeb0348fb87baf1f71303bc7d53c396]', 'v1.0'),
('SAIS-EC-004-03', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_reporting_routes', 'federal + state', 'federal + state -- ALL_STATES', 'Reporting Medicare Fraud -- The Agencies and What Each One Does', 'federal_agency | state_agency', 'medicare_fraud_reporting_routes', 'https://oig.hhs.gov/fraud/report-fraud/', 'HHS Office of Inspector General Hotline: 800-447-8477 | TTY 800-377-4950 | Medicare: 800-633-4227 | Your state Medicaid Fraud Control Unit via the state Attorney General', 'False Claims Act (31 U.S.C. sec. 3729 et seq.) | Anti-Kickback Statute (42 U.S.C. sec. 1320a-7b(b)) | Civil Monetary Penalties Law (42 U.S.C. sec. 1320a-7a) | Exclusion authority (42 U.S.C. sec. 1320a-7) | Medicaid Fraud Control Units (42 U.S.C. sec. 1396b(q); 42 CFR Part 1007)', 'VERIFIED', '2026-08-17', 'REPORT TO THE HHS OIG HOTLINE AT 800-447-8477 AND, WHERE MEDICAID IS ALSO INVOLVED, TO THE STATE MEDICAID FRAUD CONTROL UNIT. OIG can impose EXCLUSION, which bars a provider from federal health programs entirely and is usually a bigger consequence than any repayment. Say which program is involved -- Original Medicare, Medicare Advantage, or Part D -- because Part C and D route to a different integrity contractor and the wrong route stalls the report. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: c3ae23b455f7cfaacde8c5966413a69663fbe7260358b94bed5ee08f39fbe16b]', 'v1.0')
